[
  {
    "statement": "The evidence for acoustic devices to reduce human-wildlife conflict differs substantially between aquaculture systems and fishing gear contexts.",
    "citations": [
      "2775",
      "2808"
    ]
  },
  {
    "statement": "At aquaculture systems, four of six evaluated studies found that acoustic devices reduced predation on caged salmon by grey seals, harbour seals and South American sea lions.",
    "citations": [
      "2775"
    ]
  },
  {
    "statement": "At aquaculture systems, four of six evaluated studies found that acoustic devices reduced the number of harbour seals approaching fish cages.",
    "citations": [
      "2775"
    ]
  },
  {
    "statement": "Two studies found that acoustic devices did not reduce harbour seal predation at salmon farms.",
    "citations": [
      "2775"
    ]
  },
  {
    "statement": "Two studies found that acoustic devices did not reduce the presence, approach distances, group sizes or time spent around fin-fish farms by common bottlenose dolphins.",
    "citations": [
      "2775"
    ]
  },
  {
    "statement": "For fishing gear, thirty-three studies were evaluated, showing much more extensive evidence for the effectiveness of acoustic devices.",
    "citations": [
      "2808"
    ]
  },
  {
    "statement": "Five of six controlled studies on fishing gear found that acoustic devices reduced damage to fish catches and/or fishing nets caused by common bottlenose dolphins and seals.",
    "citations": [
      "2808"
    ]
  },
  {
    "statement": "One study found acoustic devices did not reduce damage to swordfish catches by California sea lions.",
    "citations": [
      "2808"
    ]
  },
  {
    "statement": "Studies on fishing gear demonstrated significant evidence for reducing entanglements.",
    "citations": [
      "2808"
    ]
  },
  {
    "statement": "Nine studies found that acoustic devices on fishing gear resulted in fewer collisions of humpback whales.",
    "citations": [
      "2808"
    ]
  },
  {
    "statement": "Nine studies found that acoustic devices on fishing gear resulted in fewer entanglements of harbour porpoises, Franciscana dolphins, beaked whales and small cetaceans.",
    "citations": [
      "2808"
    ]
  },
  {
    "statement": "The fishing gear evidence base is substantially larger than the aquaculture evidence base.",
    "citations": [
      "2808",
      "2775"
    ]
  },
  {
    "statement": "The evidence for acoustic devices on fishing gear shows broader applications across more marine mammal species and geographical locations.",
    "citations": [
      "2808"
    ]
  },
  {
    "statement": "Acoustic devices on fishing gear demonstrated effectiveness for both reducing unwanted catch/entanglements and human-wildlife conflict.",
    "citations": [
      "2808"
    ]
  },
  {
    "statement": "Aquaculture studies on acoustic devices focused primarily on predation reduction at fish farms.",
    "citations": [
      "2775"
    ]
  }
]

[
  {
    "statement": "The evidence shows different levels of effectiveness between attaching acoustically reflective objects to fishing gear and using acoustically reflective fishing gear materials for reducing marine mammal entanglement.",
    "citations": [
      "2806",
      "2807"
    ]
  },
  {
    "statement": "Two studies conducted on attaching acoustically reflective objects to fishing gear both showed no effectiveness.",
    "citations": [
      "2806"
    ]
  },
  {
    "statement": "One controlled study in the Timor Sea and Arafura Sea found that attaching metallic bead chains to fishing nets did not reduce dolphin entanglements.",
    "citations": [
      "2806"
    ]
  },
  {
    "statement": "One controlled study in the Gulf of Alaska found that attaching acrylic beads next to fishing hooks did not reduce predation on fish catches by sperm whales.",
    "citations": [
      "2806"
    ]
  },
  {
    "statement": "Using acoustically reflective fishing gear materials showed more promising results based on five studies conducted across multiple locations.",
    "citations": [
      "2807"
    ]
  },
  {
    "statement": "Two of three controlled studies in the North Sea, Bay of Fundy, and South Atlantic Ocean found that fishing nets made from acoustically reflective materials (iron-oxide or barium sulfate) had fewer entanglements of harbour porpoises than conventional fishing nets.",
    "citations": [
      "2807"
    ]
  },
  {
    "statement": "One study found that nets made from barium sulfate did not reduce dolphin entanglements.",
    "citations": [
      "2807"
    ]
  },
  {
    "statement": "Two behavioural studies examined how harbour porpoises responded to acoustically reflective materials.",
    "citations": [
      "2807"
    ]
  },
  {
    "statement": "One study found that porpoises approached both barium sulfate and conventional nets similarly.",
    "citations": [
      "2807"
    ]
  },
  {
    "statement": "One study found that porpoises used fewer echolocation clicks at barium sulfate nets.",
    "citations": [
      "2807"
    ]
  },
  {
    "statement": "Another study found that harbour porpoise echolocation activity was similar at both acoustically reflective and conventional net types.",
    "citations": [
      "2807"
    ]
  }
]

[
  {
    "statement": "Evidence shows multiple direct management interventions for boosting threatened mammal populations exist.",
    "citations": []
  },
  {
    "statement": "Direct management interventions for boosting threatened mammal populations have varying success rates.",
    "citations": []
  },
  {
    "statement": "Captive breeding and release programs demonstrate mixed results.",
    "citations": [
      "2476"
    ]
  },
  {
    "statement": "Studies from 31 locations found that captive-bred mammals had lower post-release survival rates than wild-born translocated animals.",
    "citations": [
      "2476"
    ]
  },
  {
    "statement": "Populations of mountain gazelles, Corsican red deer, Père David's deer, Eurasian otters and swift foxes increased following releases.",
    "citations": [
      "2476"
    ]
  },
  {
    "statement": "Review evidence indicates over half of mammal release programmes were considered successful.",
    "citations": [
      "2476"
    ]
  },
  {
    "statement": "Release programmes for macropods resulted in successful establishment in 61% of cases.",
    "citations": [
      "2476"
    ]
  },
  {
    "statement": "40% of released macropods survived for over five years.",
    "citations": [
      "2476"
    ]
  },
  {
    "statement": "Translocation shows promise as a management intervention for marine mammals.",
    "citations": [
      "2930",
      "2933"
    ]
  },
  {
    "statement": "Between 50% and 83% of translocated Hawaiian monk seal pups survived for at least one year.",
    "citations": [
      "2930"
    ]
  },
  {
    "statement": "The survival rates for translocated Hawaiian monk seal pups were similar to non-translocated pups born at release sites.",
    "citations": [
      "2930"
    ]
  },
  {
    "statement": "More than a quarter of translocated Hawaiian monk seals reproduced when translocation was combined with other interventions.",
    "citations": [
      "2930"
    ]
  },
  {
    "statement": "For captive-bred marine mammals, two of three Antillean manatees born in captivity and released survived for at least one year.",
    "citations": [
      "2933"
    ]
  },
  {
    "statement": "Two of 14 Florida manatees born in captivity and released survived for at least one year.",
    "citations": [
      "2933"
    ]
  },
  {
    "statement": "Holding translocated mammals in captivity before release increased survival rates.",
    "citations": [
      "2458"
    ]
  },
  {
    "statement": "Longer pre-release captivity periods improved the survival of European hedgehogs and Canada lynx.",
    "citations": [
      "2458"
    ]
  },
  {
    "statement": "Translocated animals held in captivity prior to release had higher post-release survival rates than captive-bred animals released directly.",
    "citations": [
      "2458"
    ]
  },
  {
    "statement": "Providing artificial refuges and breeding sites enhances the success of mammal release programs.",
    "citations": [
      "2453"
    ]
  },
  {
    "statement": "Release sites with artificial burrows had higher abundances of European rabbits and California ground squirrels compared to sites without artificial burrows.",
    "citations": [
      "2453"
    ]
  },
  {
    "statement": "Translocated European ground squirrels released into plugged artificial burrows had higher recapture rates than those in unplugged burrows.",
    "citations": [
      "2453"
    ]
  },
  {
    "statement": "Supplementary feeding provides population support for threatened mammals.",
    "citations": [
      "2367"
    ]
  },
  {
    "statement": "Studies found supplementary feeding increased the abundance of bank voles, red squirrels, striped mice, brown hyena and black-backed jackals.",
    "citations": [
      "2367"
    ]
  },
  {
    "statement": "Supplementary feeding increased reproductive rates in ungulates in five of eight studies.",
    "citations": [
      "2367"
    ]
  },
  {
    "statement": "Supplementary feeding increased survival in ungulates in four out of seven studies.",
    "citations": [
      "2367"
    ]
  },
  {
    "statement": "Supplementary feeding increased the proportion of striped mice that were breeding.",
    "citations": [
      "2367"
    ]
  },
  {
    "statement": "Supplementary feeding increased the number of arctic fox litters.",
    "citations": [
      "2367"
    ]
  },
  {
    "statement": "Supplementary feeding increased the litter sizes of prairie voles.",
    "citations": [
      "2367"
    ]
  },
  {
    "statement": "Genetic management techniques show limited evidence of success.",
    "citations": [
      "2473",
      "2475"
    ]
  },
  {
    "statement": "Artificial insemination resulted in fewer than half of female black-footed ferrets giving birth.",
    "citations": [
      "2473"
    ]
  },
  {
    "statement": "Artificial insemination resulted in lower pregnancy rates in giant pandas compared to natural mating.",
    "citations": [
      "2473"
    ]
  },
  {
    "statement": "Artificial insemination using preserved genetic material increased genetic diversity in captive black-footed ferret populations.",
    "citations": [
      "2475"
    ]
  },
  {
    "statement": "Artificial insemination using preserved genetic material lowered inbreeding in captive black-footed ferret populations.",
    "citations": [
      "2475"
    ]
  },
  {
    "statement": "The success of primate reintroduction varies by the rearing method used.",
    "citations": [
      "1594",
      "1596"
    ]
  },
  {
    "statement": "Most reintroduced golden lion tamarins born and reared in cages had higher mortality than wild-born tamarins.",
    "citations": [
      "1594"
    ]
  },
  {
    "statement": "Most reintroduced golden lion tamarins born and reared in cages did not survive over seven years.",
    "citations": [
      "1594"
    ]
  },
  {
    "statement": "Only two out of three black lion tamarins raised in free-ranging environments survived over four months.",
    "citations": [
      "1596"
    ]
  }
]

[
  {
    "statement": "Several potential negative impacts and limitations of acoustic deterrent devices for marine mammal conservation can be identified.",
    "citations": []
  },
  {
    "statement": "Killer whale distances from fishing vessels decreased after the first exposure to acoustic devices, suggesting habituation may occur.",
    "citations": [
      "2815"
    ]
  },
  {
    "statement": "The probability of harbour porpoises approaching within 125 meters of acoustic devices increased over 10-11 days, indicating habituation effects.",
    "citations": [
      "2816"
    ]
  },
  {
    "statement": "Acoustic deterrent devices have shown inconsistent effectiveness.",
    "citations": [
      "2775",
      "2808"
    ]
  },
  {
    "statement": "Acoustic devices did not reduce harbour seal predation at some salmon farms.",
    "citations": [
      "2775"
    ]
  },
  {
    "statement": "Acoustic devices did not reduce the presence of common bottlenose dolphins around fin-fish farms.",
    "citations": [
      "2775"
    ]
  },
  {
    "statement": "Acoustic devices on fishing vessels can reduce surfacing and echolocation rates of Indo-Pacific humpback dolphins and Australian snubfin dolphins.",
    "citations": [
      "2815"
    ]
  },
  {
    "statement": "A reduction in surfacing and echolocation rates in dolphins could potentially interfere with the dolphins' natural behaviors.",
    "citations": [
      "2815"
    ]
  },
  {
    "statement": "Acoustic devices on fishing gear were effective for some species but not others, indicating variable effectiveness.",
    "citations": [
      "2808"
    ]
  },
  {
    "statement": "Acoustic devices on fishing gear were effective in some fishing areas but not others.",
    "citations": [
      "2808"
    ]
  },
  {
    "statement": "Harmful deterrents exist at aquaculture systems and require regulation.",
    "citations": [
      "2746"
    ]
  }
]

[
  {
    "statement": "Based on evidence from the Atlantic and North Sea regions, several interventions have demonstrated effectiveness for reducing cetacean bycatch in fishing nets.",
    "citations": []
  },
  {
    "statement": "Acoustic devices on fishing gear showed the strongest evidence for reducing cetacean bycatch.",
    "citations": []
  },
  {
    "statement": "Twelve of 16 controlled studies found that acoustic devices on fishing nets resulted in harbour porpoises, common bottlenose dolphins and other cetaceans approaching nets less closely.",
    "citations": [
      "2808"
    ]
  },
  {
    "statement": "The same twelve studies also found that these cetaceans had fewer encounters with nets equipped with acoustic devices.",
    "citations": [
      "2808"
    ]
  },
  {
    "statement": "Nine studies in the North Atlantic Ocean and North Sea found that acoustic devices on fishing nets resulted in fewer entanglements of harbour porpoises, Franciscana dolphins, beaked whales and small cetaceans.",
    "citations": []
  },
  {
    "statement": "The effectiveness of acoustic devices on fishing nets varied by fishing area in some cases.",
    "citations": []
  },
  {
    "statement": "Acoustically reflective fishing gear materials showed promise for reducing cetacean bycatch.",
    "citations": [
      "2807"
    ]
  },
  {
    "statement": "Two of three controlled studies in the North Sea and Bay of Fundy found that nets made from acoustically reflective materials, such as iron-oxide or barium sulfate, had fewer entanglements of harbour porpoises than conventional fishing nets.",
    "citations": [
      "2807"
    ]
  },
  {
    "statement": "One study found that barium sulfate nets did not reduce dolphin entanglements.",
    "citations": [
      "2807"
    ]
  },
  {
    "statement": "Acoustic devices on fishing vessels showed limited evidence for reducing cetacean bycatch in Atlantic regions.",
    "citations": [
      "2815"
    ]
  },
  {
    "statement": "One controlled study in the North Atlantic Ocean found that acoustic devices on fishing vessels did not reduce predation of squid catches by Risso's dolphins.",
    "citations": [
      "2815"
    ]
  },
  {
    "statement": "Attaching acoustically reflective objects to fishing gear showed no effectiveness in reducing cetacean bycatch.",
    "citations": [
      "2806"
    ]
  },
  {
    "statement": "One controlled study found that attaching metallic bead chains to fishing nets did not reduce dolphin entanglements.",
    "citations": [
      "2806"
    ]
  },
  {
    "statement": "Escape devices fitted to encircling nets showed some promise for reducing unwanted catch.",
    "citations": [
      "2703"
    ]
  },
  {
    "statement": "There is limited specific evidence for cetacean bycatch reduction using escape devices in the Atlantic and North Sea regions.",
    "citations": [
      "2703"
    ]
  }
]

[
  {
    "statement": "Evidence for the success of releasing hand-reared or captive-bred manatees back into the wild in the Americas shows mixed but generally positive outcomes.",
    "citations": []
  },
  {
    "statement": "Approximately three-quarters of Antillean manatees that were captive-reared and released in the South Atlantic Ocean in Brazil were known to survive for at least one year.",
    "citations": [
      "2926"
    ]
  },
  {
    "statement": "Some captive-reared Antillean manatees that were released in the South Atlantic Ocean survived for more than seven years.",
    "citations": [
      "2926"
    ]
  },
  {
    "statement": "Two-thirds of Florida manatees that were captive-reared and released in water bodies in Florida survived for at least one year.",
    "citations": [
      "2926"
    ]
  },
  {
    "statement": "Most captive-reared Antillean manatees released back into the wild in the South Atlantic Ocean reproduced.",
    "citations": [
      "2926"
    ]
  },
  {
    "statement": "The reproduction of captive-reared Antillean manatees released into the wild indicates successful integration.",
    "citations": [
      "2926"
    ]
  },
  {
    "statement": "Three captive-reared West Indian manatee calves either died before or after release, had to be returned to captivity after release, or survived in the wild only with supplemental feeding.",
    "citations": [
      "2926"
    ]
  },
  {
    "statement": "Evidence shows lower success rates for releasing manatees that were specifically captive-bred.",
    "citations": [
      "2933"
    ]
  },
  {
    "statement": "Two of three Antillean manatees born in captivity and released in the Porto de Pedras estuary in Brazil survived for at least one year without further intervention.",
    "citations": [
      "2933"
    ]
  },
  {
    "statement": "Two of fourteen Florida manatees born in captivity and released in water bodies in Florida survived for at least one year without further intervention.",
    "citations": [
      "2933"
    ]
  },
  {
    "statement": "General rehabilitation data shows that 10-100% of manatees released after rehabilitation in captivity survived during post-release monitoring periods.",
    "citations": [
      "2925"
    ]
  },
  {
    "statement": "Post-release monitoring periods for rehabilitated manatees ranged from three days to five years.",
    "citations": [
      "2925"
    ]
  },
  {
    "statement": "Rehabilitated manatees were monitored in various locations including the Gulf of Mexico, the Indian River Lagoon, and water bodies in Florida.",
    "citations": [
      "2925"
    ]
  }
]

[
  {
    "statement": "Catch protection devices on longlines showed mixed effectiveness in reducing human-wildlife conflict.",
    "citations": []
  },
  {
    "statement": "Two of four studies found that net sleeves or cage and chain devices on fishing hooks reduced damage to fish catches by sperm whales, killer whales and toothed whales.",
    "citations": [
      "2821"
    ]
  },
  {
    "statement": "Two other studies found that attaching 'umbrella' or 'spider' devices on fishing hooks did not reduce predation and/or damage to fish catches by sperm whales or toothed whales.",
    "citations": [
      "2821"
    ]
  },
  {
    "statement": "One study found that catch protection devices made from streamers reduced dolphin predation on fish bait, but only during the first two trials.",
    "citations": [
      "2821"
    ]
  },
  {
    "statement": "Modifying fishing pots and traps showed more consistent positive outcomes for reducing human-wildlife conflict.",
    "citations": []
  },
  {
    "statement": "Two controlled studies found that installing wire grids or steel bars on fishing trap-nets or bag-nets, along with strengthened netting or other modifications to prevent seal access, reduced damage to salmon catches by seals.",
    "citations": [
      "2822"
    ]
  },
  {
    "statement": "One study found that one of two methods of securing crab pot doors with a bungee cord reduced common bottlenose dolphin interactions.",
    "citations": [
      "2822"
    ]
  },
  {
    "statement": "One study found that installing wire grids on trap-nets, along with strengthened netting, resulted in higher catches of undamaged salmon but not whitefish.",
    "citations": [
      "2822"
    ]
  },
  {
    "statement": "The higher catches of undamaged salmon were likely due to reduced seal predation.",
    "citations": [
      "2822"
    ]
  },
  {
    "statement": "Both catch protection devices and modified fishing pots showed effectiveness in reducing entanglements and unwanted catch.",
    "citations": []
  },
  {
    "statement": "Catch protection devices resulted in fewer unwanted catches of toothed whales.",
    "citations": [
      "2821"
    ]
  },
  {
    "statement": "Modified fishing pots reduced the number of Australian sea lion pups or grey seals and harbour seals that entered or became trapped in pots.",
    "citations": [
      "2822"
    ]
  }
]

