[
  {
    "statement": "The benefits of using acoustic devices on fishing gear include reduced entanglements and collisions for marine mammals, including harbour porpoises.",
    "citations": []
  },
  {
    "statement": "Acoustic devices on fishing nets and cod traps resulted in fewer entanglements of harbour porpoises, Franciscana dolphins, beaked whales and small cetaceans.",
    "citations": [
      "2808"
    ]
  },
  {
    "statement": "One study found that fishing nets with a 'complete' set of acoustic devices had fewer entanglements of harbour porpoises.",
    "citations": [
      "2808"
    ]
  },
  {
    "statement": "Controlled studies found that acoustic devices resulted in harbour porpoises, common bottlenose dolphins, and other species approaching nets less closely.",
    "citations": [
      "2808"
    ]
  },
  {
    "statement": "Controlled studies found that acoustic devices resulted in some species having fewer encounters with nets.",
    "citations": [
      "2808"
    ]
  },
  {
    "statement": "Controlled studies found that acoustic devices resulted in reduced activity for some species in surrounding areas.",
    "citations": [
      "2808"
    ]
  },
  {
    "statement": "The effectiveness of acoustic devices varies by location.",
    "citations": [
      "2808"
    ]
  },
